function activateBarrierdef(player) {
    let playerscGroup = room.getPlayerDiscProperties(player.id).cGroup;
    room.setPlayerDiscProperties(player.id, {cGroup: playerscGroup | room.CollisionFlags.c0})
}

function removeBarrierdef(player) {
    let playerscGroup = room.getPlayerDiscProperties(player.id).cGroup;
    if((playerscGroup & room.CollisionFlags.c0) !== 0) {
        room.setPlayerDiscProperties(player.id, {cGroup: playerscGroup - room.CollisionFlags.c0})
    }
}

function activateBarrierbdef(player) {
    let playerscGroup = room.getPlayerDiscProperties(player.id).cGroup;
    room.setPlayerDiscProperties(player.id, {cGroup: playerscGroup | room.CollisionFlags.c1})
}

function removeBarrierbdef(player) {
    let playerscGroup = room.getPlayerDiscProperties(player.id).cGroup;
    if((playerscGroup & room.CollisionFlags.c1) !== 0) {
        room.setPlayerDiscProperties(player.id, {cGroup: playerscGroup - room.CollisionFlags.c1})
    }
}

function altıdefengel() {
  let yasaklananoyncular = room.getPlayerList().filter(p => p.team == 2).sort((p1, p2) => p2.position.x - p1.position.x);

    

    for (let i = 0; i < yasaklananoyncular.length; i++) {
        if (i < oyunculimiti) {
            removeBarrierbdef(yasaklananoyncular[i]);
        } else {
            activateBarrierbdef(yasaklananoyncular[i]);
        }
    }


	let yasaklananoyncularr = room.getPlayerList()
        .filter(p => p.team == 1) 
        .sort((p1, p2) =>  p1.position.x - p2.position.x ); 

  

    for (let i = 0; i < yasaklananoyncularr.length; i++) {
        if (i < oyunculimiti) {
            removeBarrierdef(yasaklananoyncularr[i]); 
        } else {
            activateBarrierdef(yasaklananoyncularr[i]); 
        }
    }
}


function macBitisKontrol() {
    if (!oyunmodu.otopower) return; 

    let süre = room.getScores().time; 
    let hedefSure = 6 * 60; 

    if (süre >= hedefSure && !macbitti) {
        room.stopGame(); 
        room.sendAnnouncement("Maç bitti.", null, 0xff0000, "bold", 2);
        macbitti = true; 
    }
}

function oyuncuVarMi(takimObj, oyuncuAdi) {
    return Object.values(takimObj).some(poz => poz.name === oyuncuAdi);
}

